namespace sv_7f0b2efaeab444379417c4377b0fe7a9.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;
    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query for low-stock items at a given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds for the given warehouse.
    /// Polling is reference-counted: multiple subscribers share one timer.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(warehouseId, _pollCts.Token);
        }
    }

    /// <summary>
    /// Decrements subscriber count; stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    /// <summary>
    /// Restarts polling with a new warehouse ID (e.g., after warehouse switch).
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        if (_subscriberCount > 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(warehouseId, _pollCts.Token);
        }
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                var count = await GetLowStockCountAsync(warehouseId);
                _lastLowStockCount = count;
                OnAlertDataChanged?.Invoke();
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        OnAlertDataChanged = null;
    }
}

