@page "/dashboard"
@rendermode InteractiveServer
@using sv_7f0b2efaeab444379417c4377b0fe7a9.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site: @CurrentWarehouseName</h5>
        <p class="card-text">
            Low-Stock Alerts:
            <AlertBadge />
        </p>
        <small class="text-muted">Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
    </div>
</div>

<div class="alert alert-info">
    <strong>How it works:</strong> This page polls for low-stock items every 10 seconds.
    The sidebar badge and this page both update simultaneously when new data arrives.
    Switch warehouses using the dropdown in the top bar — all components react immediately.
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? "Unknown";

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
    }

    private void OnWarehouseChanged()
    {
        AlertService.RestartPolling(WarehouseState.CurrentWarehouseId);
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertDataChanged()
    {
        _lastUpdate = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        AlertService.StopPolling();
    }
}

